with upsert_courses as (
  insert into public.saved_courses (source_provider, source_course_id, name, normalized_name, city, state, updated_at)
  select 'manual_seed', course_key, course_name, course_key, city, state, now()
  from repair_course_seed
  on conflict (normalized_name, city, state) do update set
    name = excluded.name,
    source_provider = excluded.source_provider,
    source_course_id = excluded.source_course_id,
    updated_at = now()
  returning id, normalized_name, city, state
), target_courses as (
  select u.id, s.*
  from upsert_courses u
  join repair_course_seed s on s.course_key = u.normalized_name and s.city is not distinct from u.city and s.state is not distinct from u.state
)
insert into public.saved_course_holes (saved_course_id, hole_number, par, handicap_index, updated_at)
select
  c.id,
  hole_number,
  c.pars[hole_number],
  c.hcps[hole_number],
  now()
from target_courses c
cross join generate_series(1,18) as hole_number
on conflict (saved_course_id, hole_number) do update set
  par = excluded.par,
  handicap_index = excluded.handicap_index,
  updated_at = now();

select
  count(distinct c.id) as repaired_courses,
  count(h.id) as repaired_hole_rows
from public.saved_courses c
join public.saved_course_holes h on h.saved_course_id = c.id
where c.normalized_name in (select course_key from repair_course_seed);

